 {(view==="Anunciantes"||view==="Locutores")&&<><div className="pro-toolbar"><SearchBox value={query} onChange={setQuery} placeholder={view==="Anunciantes"?"Buscar anunciante":"Buscar locutor"}/></div><DataTable headers={view==="Anunciantes"?["Anunciante","Documento","Responsável","Contato",""]:["Locutor","Contato","Contratos","Comissão padrão",""]}>{(view==="Anunciantes"?clients:speakers).filter(x=>x.name.toLowerCase().includes(query.toLowerCase())).map((x:any)=><TableRow key={x.id}><TableCell><strong>{x.name}</strong></TableCell>{view==="Anunciantes"?<><TableCell>{x.document||"—"}</TableCell><TableCell>{x.contact||"—"}</TableCell><TableCell>{x.phone||"—"}<small>{x.email}</small></TableCell></>:<><TableCell>{x.phone||"—"}<small>{x.email}</small></TableCell><TableCell>{contracts.filter(c=>c.speakerId===x.id).length}</TableCell><TableCell><span className="pro-badge teal">30%</span></TableCell></>}<TableCell><button className="icon-btn" title="Editar cadastro" aria-label={`Editar ${x.name}`} onClick={()=>open(view==="Anunciantes"?"client":"speaker",x)}><Pencil size={16}/></button></TableCell></TableRow>)}</DataTable>{!(view==="Anunciantes"?clients:speakers).length&&<Empty text={view==="Anunciantes"?"Nenhum anunciante cadastrado":"Nenhum locutor cadastrado"} icon={Users}/>}</>}
